// Creating a plain JavaScript object
const product = {
  id: 101,
  name: 'Laptop',
  price: 999.99,
  inStock: true
}

// Example: a function that extracts object keys
function getKeys(obj) {
  return Object.keys(obj);
}

// Example: a function that makes properties optional
function makePartial(obj) {
  return { ...obj };
}

// Example: a function that picks properties
function pickProperties(obj, keys) {
  const result = {};
  for (const key of keys) {
    if (key in obj) {
      result[key] = obj[key];
    }
  }
  return result;
}

